<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeAttributes;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeFilter;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeCursor;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeReadGateway;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeSlide;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ConsentPurposeVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ConsentPurposeReadGateway $readGateway,
        private readonly ConsentPurposeWriteGateway $writeGateway,
        private readonly TenantVisibilityService $tenantVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(ConsentPurpose $content): ConsentPurposeAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(ConsentPurpose $content): ConsentPurposeAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(ConsentPurposeAttributes $attributes, ?ConsentPurpose $original = null): ConsentPurposeAttributes
    {
        $this->logDebug("Copy with fixed for Consent purpose");
        $span = $this->startSpan("Copy with fixed for  Consent purpose");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new ConsentPurposePresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(ConsentPurposeAttributes $attributes, ?ConsentPurpose $original = null): ConsentPurposeAttributes
    {
        $this->logDebug("Copy with hidden for Consent purpose");
        $span = $this->startSpan("Copy with hidden for  Consent purpose");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|ConsentPurposeRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Consent purpose");
        $span = $this->startSpan("Check visibility of an iterator for  Consent purpose");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new ConsentPurposeRef($value));
            } elseif ($value instanceof ConsentPurposeRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new ConsentPurposeFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(ConsentPurposeFilter $filter, ?ConsentPurposeCursor $cursor = null): ConsentPurposeSlide
    {
        $this->logDebug("List visibles for Consent purpose");
        $span = $this->startSpan("List visibles for  Consent purpose");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (ConsentPurpose $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(ConsentPurposeFilter $filter): int
    {
        $this->logDebug("Count visibles for Consent purpose");
        $span = $this->startSpan("Count visibles for  Consent purpose");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(ConsentPurposeFilter $filter, ?ConsentPurposeCursor $cursor = null): ConsentPurposeSlide
    {
        $this->logDebug("List visibles for update for Consent purpose");
        $span = $this->startSpan("List visibles for update for  Consent purpose");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (ConsentPurpose $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(ConsentPurposeFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Consent purpose");
        $span = $this->startSpan("Count visibles for update for  Consent purpose");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(ConsentPurposeRef $ref): ?ConsentPurpose
    {
        $this->logDebug("Retrieve visible for Consent purpose");
        $span = $this->startSpan("Retrieve visible for  Consent purpose");
        try {
            $filter = new ConsentPurposeFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(ConsentPurposeRef $ref): ?ConsentPurpose
    {
        $this->logDebug("Retrieve visible for update for Consent purpose");
        $span = $this->startSpan("Retrieve visible for update for  Consent purpose");
        try {
            $filter = new ConsentPurposeFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?ConsentPurposeRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Consent purpose");
        $span = $this->startSpan("Check fields for fix for Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeCollectNonEditableFields(ConsentPurpose::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?ConsentPurposeRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Consent purpose");
        $span = $this->startSpan("Check fields to hide for  Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(ConsentPurposeAttributes $attributes): ConsentPurposeAttributes
    {
        $this->logDebug("Check visibility of parent references for Consent purpose");
        $span = $this->startSpan("Check visibility of parent references for  Consent purpose");
        try {
            $tenant = $attributes->getTenant();
            if (null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant)) {
                throw new NotFoundException("Unknown Tenant " . ($tenant->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(ConsentPurposeFilter $filter): ConsentPurposeFilter
    {
        $this->logDebug("Compose visibility filter for Consent purpose");
        $span = $this->startSpan("Compose visibility filter for  Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeRestrictFilterToVisibility($filter));
            return $result->consentPurposeFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(ConsentPurpose $value): bool
    {
        $this->logDebug("Check if item is visible for Consent purpose");
        $span = $this->startSpan("Check if item is visible for  Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(ConsentPurpose $content, bool $inlist): ConsentPurposeAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Consent purpose");
        $span = $this->startSpan("Prepare hydration to visible data for Consent purpose");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new ConsentPurposeEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
